def copy_agent_allocations(apps, schema_editor):
    """Preserve existing agent-allocation data before the source columns are
    dropped. Clinton's restructure split allocation_collection_* out of
    ProjectTitanPlotsAllocation into its own table but didn't carry the data
    across — do it here so nothing is lost on prod."""
