    Agent.objects.bulk_create(
        [
            Agent(
                plot_number=r.plot_number,
                allocation_collection_code=r.allocation_collection_code,
                allocation_collection_agent=r.allocation_collection_agent,
                allocation_collection_group=r.allocation_collection_group,
            )
            for r in rows.iterator()
        ],
        batch_size=500,
    )


